import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.mRCPFc5l.js";const g=JSON.parse('{"title":"JustEnoughAccuracy","description":"","frontmatter":{"title":"JustEnoughAccuracy","order":10},"headers":[],"relativePath":"mods/just-enough-accuracy.md","filePath":"mods/just-enough-accuracy.md","lastUpdated":1786957039000}'),i={name:"mods/just-enough-accuracy.md"};function n(s,t,d,c,l,u){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="justenoughaccuracy" tabindex="-1">JustEnoughAccuracy <a class="header-anchor" href="#justenoughaccuracy" aria-label="Permalink to &quot;JustEnoughAccuracy&quot;">​</a></h1><blockquote><p>A new <strong>angle-level accuracy judgment</strong> (JEA) — reads the same hit data as the official judgment but grades it with its own fixed scoring table, <strong>coexisting with and never affecting</strong> the original judgment. Supports viewing judgment details and exporting gameplay data.</p><p>Project: <a href="https://github.com/adofaiex/JustEnoughAccuracy" target="_blank" rel="noreferrer">https://github.com/adofaiex/JustEnoughAccuracy</a></p></blockquote><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><ol><li><strong>New <code>JEA</code> accuracy</strong> — a separate accuracy independent from the official judgment</li><li><strong>Detailed results viewer</strong> — after each level, open a window to view per-tile details, search and scroll through the whole session</li><li><strong>Export &amp; share</strong> — export the session to a <code>.yaml</code> file or an interactive <code>.html</code> chart</li></ol><h2 id="judgment-mechanism" tabindex="-1">Judgment Mechanism <a class="header-anchor" href="#judgment-mechanism" aria-label="Permalink to &quot;Judgment Mechanism&quot;">​</a></h2><p>JEA is a fixed <strong>point-allocation</strong> judgment:</p><ul><li>Each tile&#39;s raw <strong>angle deviation is normalized to a reference BPM</strong> (<code>deviation × 100 / BPM</code>), so the same timing error in milliseconds grades identically on any chart</li><li>The normalized deviation is graded against a <strong>fixed band table</strong>, with <strong>linear interpolation</strong> between neighboring anchors — so every point value (95, 97, 98.4, …) is reachable, not just the anchors</li></ul><table tabindex="0"><thead><tr><th>Normalized Deviation</th><th>Score</th></tr></thead><tbody><tr><td>≤ 1.7°</td><td>100</td></tr><tr><td>2.0°</td><td>96</td></tr><tr><td>2.4°</td><td>92</td></tr><tr><td>2.8°</td><td>88</td></tr><tr><td>3.2°</td><td>84</td></tr><tr><td>3.6°</td><td>80</td></tr><tr><td>4.0°</td><td>75</td></tr><tr><td>4.5°</td><td>70</td></tr><tr><td>5.0°</td><td>62</td></tr><tr><td>5.5°</td><td>54</td></tr><tr><td>6.0°</td><td>46</td></tr><tr><td>6.6°</td><td>36</td></tr><tr><td>7.2°</td><td>26</td></tr><tr><td>8.0°</td><td>15</td></tr><tr><td>&gt; 8.0°</td><td>0</td></tr></tbody></table><h3 id="other-rules" tabindex="-1">Other Rules <a class="header-anchor" href="#other-rules" aria-label="Permalink to &quot;Other Rules&quot;">​</a></h3><ul><li><strong>Combo</strong>: consecutive tiles scoring ≥ 50 build a combo. The combo is for display only — it <strong>does not multiply</strong>, so JEA accuracy is capped at 100%</li><li><strong>Empty-press tolerance</strong>: mirrors the official <code>consecutiveMultipressCounter &gt; 8</code> rule — the first 8 consecutive empty presses are forgiven, after which each costs −100 and resets the combo</li><li><strong>Miss / overload</strong>: each failed tile scores −100</li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>JEA Acc = TotalScore / (Tiles × 100)   (up to 4 decimal places)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h2 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h2><p>Exported files are written to <code>&lt;mod directory&gt;/reports</code>.</p><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>Supported loaders: UnityModManager, MelonLoader, BepInEx</li><li>Game version: ≥ 3.1.0</li></ul><h2 id="integration" tabindex="-1">Integration <a class="header-anchor" href="#integration" aria-label="Permalink to &quot;Integration&quot;">​</a></h2><p>Install <a href="./not-enough-accuracy">NotEnoughAccuracy</a> (NEA) — its data will also be displayed in the detail viewer and exports.</p>',17)])])}const p=e(i,[["render",n]]);export{g as __pageData,p as default};
